#include <set>
#include "mpp/SceneDocument.h"
using namespace std;
namespace mpp { DiagnosticBag SceneDocument::validate() const { DiagnosticBag d; if(version!=CurrentVersion)d.error("MPP-SCENE-001","Unsupported Scene version.",{sourcePath}); if(name.empty())d.error("MPP-SCENE-002","Scene name is required.",{sourcePath}); set<string> ids; for(auto const&m:models){if(m.id.empty()||!ids.insert(m.id).second)d.error("MPP-SCENE-003","Model IDs must be non-empty and unique.",{sourcePath},m.id); if(m.source==SceneModelSource::MppModel&&m.file.empty())d.error("MPP-SCENE-004","MPP model file is required.",{sourcePath},m.id); if(m.materialBinding.empty())d.warning("MPP-SCENE-005","Model has no logical material binding.",{sourcePath},m.id);} for(auto const&l:lights)if(l.id.empty()||!ids.insert(l.id).second)d.error("MPP-SCENE-006","Light IDs must be non-empty and unique.",{sourcePath},l.id); if(camera.nearPlane<=0||camera.farPlane<=camera.nearPlane)d.error("MPP-SCENE-007","Camera clip distances are invalid.",{sourcePath},"camera"); if(environmentBinding.empty())d.warning("MPP-SCENE-008","Scene has no logical environment binding.",{sourcePath},"environment"); return d; } }
